import URLSearchParams from './classes/URLSearchParams.js'
import FormData from './classes/FormData.js'
import zlib from 'zlib'
import ZlibHeaderTransformStream from '../../helpers/ZlibHeaderTransformStream.js'

const unzipOptions = {
  flush: zlib.constants.Z_SYNC_FLUSH,
  finishFlush: zlib.constants.Z_SYNC_FLUSH
}

const brotliOptions = {
  flush: zlib.constants.BROTLI_OPERATION_FLUSH,
  finishFlush: zlib.constants.BROTLI_OPERATION_FLUSH
}

const createUnzip = () => zlib.createUnzip(unzipOptions)
const brotliDecompress = typeof zlib.createBrotliDecompress === 'function'
  ? () => zlib.createBrotliDecompress(brotliOptions)
  : null

class NodeResponseStream {
  constructor(res, config, method, streams) {
    this.statusCode = res.statusCode
    this.method = method
    this.decompress = config.decompress
    this.streams = streams
    this.createUnzip = createUnzip
    this.brotliDecompress = brotliDecompress
    this.headerTransform = ZlibHeaderTransformStream
  }
}

export default {
  isNode: true,
  NodeResponseStream,
  classes: {
    URLSearchParams,
    FormData,
    Blob: typeof Blob !== 'undefined' && Blob || null
  },
  protocols: [ 'http', 'https', 'file', 'data' ]
};

